import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/** The example card is inlined as SVG at build time, so it is part of the page itself and not a separate image to wait for. It is generated by scripts/make-hero.mjs from project tokens and has no text or bitmaps. */
export function ExampleCardArt() {
  const source = readFileSync(join(process.cwd(), 'public/art/example-card.svg'), 'utf8').trim()
    .replace(/ width="\d+" height="\d+"/, ' width="300" height="420" focusable="false"');
  return <div className="cardimg-inline" role="img" aria-label="Example wanted-poster card with an invented comic car. Not a real card." dangerouslySetInnerHTML={{ __html: source }} />;
}
